-- Exact 5,775 production-history navigation keys. Preserve raw payload precision and task-run/task joins.
SELECT DISTINCT v.* FROM local_identity.history_versions v
 JOIN local_identity.history_episode_records r USING(owner_id,table_name,row_key,payload_sha256)
 WHERE v.owner_id='644f8c5a-b668-48a3-8a25-94c4e502fa04';

-- Preserve account label snapshots used by historyEpisodes catalog fallback.
SELECT v.* FROM local_identity.history_versions v WHERE v.owner_id='644f8c5a-b668-48a3-8a25-94c4e502fa04' AND v.table_name='public.accounts'
 AND v.payload->>'id' IN(SELECT e.account_id::text FROM public.episodes e UNION SELECT ep.payload->>'account_id' FROM local_identity.history_versions ep JOIN local_identity.history_episode_records r USING(owner_id,table_name,row_key,payload_sha256) WHERE ep.owner_id='644f8c5a-b668-48a3-8a25-94c4e502fa04' AND ep.table_name='public.episodes');
